WITH enriched AS (SELECT id, location, ROW_NUMBER() OVER w_part AS event_seq, ROUND(budget / SUM(budget) OVER (PARTITION BY dept_name), 4) AS budget_share, PERCENT_RANK() OVER (PARTITION BY dept_name, location ORDER BY budget ASC) AS budget_percent_rank FROM departments WINDOW w_part AS (PARTITION BY dept_name ORDER BY budget ASC, id ASC)) SELECT id, location, event_seq, budget_percent_rank FROM enriched ORDER BY budget_percent_rank DESC;
